customCSS:
/* AutoDrive Motors site styles */
:root{--ad-ink:#16202c;--ad-muted:#5b6673;--ad-accent:#0b5cad;--ad-accent-dark:#084684;--ad-line:#e3e7ec;--ad-soft:#f5f7fa;}
.ad-section{max-width:1100px;margin:8px auto 24px;padding:0 4px;}
.ad-eyebrow{font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--ad-accent);margin:0 0 6px;}
.ad-h2{font-size:26px;line-height:1.25;font-weight:700;color:var(--ad-ink);margin:0 0 18px;}
.ad-h3{font-size:20px;font-weight:700;color:var(--ad-ink);margin:0 0 8px;}
.ad-muted{color:var(--ad-muted);font-size:14px;line-height:1.55;margin:0;}
.ad-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px;}
.ad-card{background:#fff;border:1px solid var(--ad-line);border-radius:12px;padding:22px;}
.ad-card h3,.ad-strip h3{font-size:17px;font-weight:700;margin:10px 0 6px;color:var(--ad-ink);}
.ad-card p,.ad-strip p{font-size:14px;line-height:1.55;color:var(--ad-muted);margin:0;}
.ad-num{display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;border-radius:50%;background:var(--ad-soft);color:var(--ad-accent);font-weight:700;font-size:14px;}
.ad-strip{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin-top:16px;background:var(--ad-soft);border-radius:12px;padding:22px;}
.ad-form-head{margin:4px 0 12px;}
.ad-footer{border-top:1px solid var(--ad-line);margin-top:24px;padding:20px 4px;text-align:center;font-size:14px;color:var(--ad-ink);}
.ad-footer p{margin:4px 0;}
/* forms (screen flows) */
.forceCommunityFlowCommunity{background:#fff;border:1px solid var(--ad-line);border-radius:12px;padding:20px 22px;box-shadow:0 1px 2px rgba(22,32,44,.04);margin-bottom:24px;}
.forceCommunityFlowCommunity .slds-form-element__label{font-weight:600;color:var(--ad-ink);font-size:13px;}
.forceCommunityFlowCommunity .slds-input,.forceCommunityFlowCommunity .slds-textarea,.forceCommunityFlowCommunity .slds-select,.forceCommunityFlowCommunity .slds-combobox__input{border-radius:8px;min-height:40px;}
.forceCommunityFlowCommunity .slds-button_brand,.forceCommunityFlowCommunity .slds-button--brand{background:var(--ad-accent);border-color:var(--ad-accent);border-radius:8px;padding:4px 22px;min-height:42px;font-weight:600;}
.forceCommunityFlowCommunity .slds-button_brand:hover,.forceCommunityFlowCommunity .slds-button--brand:hover{background:var(--ad-accent-dark);border-color:var(--ad-accent-dark);}
@media (max-width:768px){.ad-h2{font-size:22px;}.ad-card,.ad-strip,.forceCommunityFlowCommunity{padding:16px;}}
